1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type QuoteResult = {
19	  premium: number;
20	};
21	
22	export type ScenarioResults = {
23	  results: QuoteResult[];
24	};
25	
26	const PROCESSING_FEE = 5;
27	
28	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
38	
39	const addPercent = (amount: number, percent: number): number =>
40	  amount + (amount * percent) / 100;
41	
42	const policyBasePremium = (items: Item[]): number =>
43	  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
44	
45	const roundPremiumInMHPCOsFavor = (amount: number): number =>
46	  Math.ceil(amount);
47	
48	const quotePremium = (items: Item[]): number =>
49	  roundPremiumInMHPCOsFavor(
50	    addPercent(policyBasePremium(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
51	      PROCESSING_FEE,
52	  );
53	
54	export const runScenario = (scenario: Scenario): ScenarioResults => ({
55	  results: scenario.steps.map((step) => ({
56	    premium: quotePremium(step.items ?? []),
57	  })),
58	});
